    40	    ledger.record(outcome({ fetchId: 'f2', status: 'denied', failureClass: 'blocked', reason: 'policy' }));
    41	    ledger.record(outcome({ fetchId: 'f3', status: 'denied', failureClass: 'payment-required', httpStatus: 402 as unknown as number, origin: { url: 'u', httpStatus: 402 } }));
    42	    ledger.record(outcome({ fetchId: 'f4', status: 'denied', failureClass: 'token-rejected', origin: { url: 'u', httpStatus: 403 } }));
    43	    const s = summarize(ledger.entries);
    44	    expect(s.total).toBe(4);
    45	    expect(s.fulfilled).toBe(1);
    46	    expect(s.denied).toBe(3);
    47	    expect(s.byFailureClass).toEqual({ blocked: 1, 'payment-required': 1, 'token-rejected': 1 });
    48	    expect(s.spendMicros).toBe(1000);
    49	  });
    50	});
    51	
    52	describe('reconcile', () => {
    53	  it('passes on a healthy ledger', () => {
    54	    const ledger = new AuditLedger({ clock });
    55	    ledger.record(outcome({ fetchId: 'f1', price: { unitsMicros: 1000, currency: 'USD' }, settlementRef: 'settle_x', rail: 'x402' }));
    56	    ledger.record(outcome({ fetchId: 'f2', status: 'denied', failureClass: 'blocked' }));
    57	    const rep = reconcile(ledger.entries);
    58	    expect(rep.ok).toBe(true);
    59	    expect(rep.problems).toEqual([]);
    60	  });
    61	
    62	  it('flags a fulfilled row missing settlementRef', () => {
    63	    const ledger = new AuditLedger({ clock });
    64	    ledger.record(outcome({ fetchId: 'f1', price: { unitsMicros: 1000, currency: 'USD' } }));
    65	    const rep = reconcile(ledger.entries);
    66	    expect(rep.ok).toBe(false);
    67	    expect(rep.checks.fulfilledHasSettlement).toBe(false);
    68	  });
    69	
    70	  it('flags a denied row without a failure class', () => {
    71	    const ledger = new AuditLedger({ clock });
    72	    ledger.record(outcome({ fetchId: 'f1', status: 'denied' }));
    73	    const rep = reconcile(ledger.entries);
    74	    expect(rep.checks.deniedHasFailureClass).toBe(false);
    75	  });
    76	
    77	  it('flags a seq gap', () => {
    78	    const rows = [
    79	      { seq: 1, fetchId: 'a', tenantId: 't', url: 'u', status: 'denied', failureClass: 'blocked', startedAt: 't', completedAt: 't', recordedAt: 't' },
    80	      { seq: 3, fetchId: 'b', tenantId: 't', url: 'u', status: 'denied', failureClass: 'blocked', startedAt: 't', completedAt: 't', recordedAt: 't' },
    81	    ];
    82	    const rep = reconcile(rows);
    83	    expect(rep.checks.seqGapFree).toBe(false);
    84	  });
    85	});
