    88	  it('renders a readable report with all three classes', () => {
    89	    const ledger = new AuditLedger({ clock });
    90	    ledger.record(outcome({ fetchId: 'f1', price: { unitsMicros: 1000, currency: 'USD' }, rail: 'x402', settlementRef: 's' }));
    91	    ledger.record(outcome({ fetchId: 'f2', status: 'denied', failureClass: 'blocked' }));
    92	    ledger.record(outcome({ fetchId: 'f3', status: 'denied', failureClass: 'payment-required' }));
    93	    const text = renderDashboard(ledger.entries);
    94	    expect(text).toContain('blocked=1');
    95	    expect(text).toContain('payment-required=1');
